/**
 * Marpione (marpi1) — Antigravity UI Sidecar & Inline Chat Bridge
 *
 * 1. Serves the Aux Pane Marp Slide Deck Viewer at /view.html (?file=/path/to/slides.md)
 * 2. Exposes /api/bridge-config + CORS headers so inline <agent-embed> widgets
 *    generated by marpione.py can post slides directly into the active Antigravity
 *    conversation via /_sidecar/send-message on any host (macOS, Linux/derek).
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, statSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { SidecarApp, Response } from 'sidecar_sdk';

const app = new SidecarApp();
const CURRENT_DIR = dirname(fileURLToPath(import.meta.url));
const MARPIONE_PY = join(CURRENT_DIR, 'marpione.py');

function getAppDataDir() {
  if (process.env.ANTIGRAVITY_APP_DATA_DIR) {
    return resolve(process.env.ANTIGRAVITY_APP_DATA_DIR);
  }
  const home = homedir();
  const candidates = [
    join(home, '.gemini', 'antigravity'),
    join(home, 'Library', 'Application Support', 'Antigravity'),
    join(home, '.config', 'Antigravity'),
    join(home, '.local', 'share', 'Antigravity'),
  ];
  for (const c of candidates) {
    if (existsSync(c)) return c;
  }
  return candidates[0];
}

function getActiveSessionId(explicitId) {
  if (explicitId && typeof explicitId === 'string' && explicitId.trim()) {
    return explicitId.trim();
  }
  if (process.env.ANTIGRAVITY_CONVERSATION_ID) {
    return process.env.ANTIGRAVITY_CONVERSATION_ID.trim();
  }
  const brainDir = join(getAppDataDir(), 'brain');
  if (!existsSync(brainDir)) return 'standalone';

  const entries = readdirSync(brainDir, { withFileTypes: true });
  const list = [];
  for (const entry of entries) {
    if (!entry.isDirectory() || entry.name.startsWith('.') || entry.name === 'tempmediaStorage') {
      continue;
    }
    const sessionPath = join(brainDir, entry.name);
    const transcript = join(sessionPath, '.system_generated', 'logs', 'transcript.jsonl');
    const target = existsSync(transcript) ? transcript : sessionPath;
    try {
      list.push({ id: entry.name, mtimeMs: statSync(target).mtimeMs });
    } catch {
      // ignore
    }
  }
  list.sort((a, b) => b.mtimeMs - a.mtimeMs);
  return list.length > 0 ? list[0].id : 'standalone';
}

function normalizeFilePath(rawPath) {
  if (!rawPath || typeof rawPath !== 'string') return null;
  let p = rawPath.trim();
  if (p.startsWith('file://')) {
    try {
      p = fileURLToPath(p);
    } catch {
      p = decodeURIComponent(p.replace(/^file:\/\//, ''));
    }
  }
  if (p.startsWith('~/')) {
    p = join(homedir(), p.slice(2));
  }
  p = resolve(p);
  return existsSync(p) ? p : null;
}

const AUX_VIEW_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Marpione Slides 🎭</title>
  <script src="https://www.gstatic.com/antigravity/web/dev/tailwindcss.min.js"></script>
</head>
<body class="bg-[var(--background)] text-[var(--foreground)] antialiased p-3 h-screen flex flex-col gap-2 overflow-hidden select-none">
  <div class="flex items-center gap-2 flex-wrap bg-[var(--card)] border border-[var(--border)] rounded-xl p-2.5">
    <span class="px-2 py-0.5 rounded-md text-xs font-semibold bg-[var(--secondary)] text-[var(--secondary-foreground)]">
      🎭 Marpione
    </span>
    <input id="deck-input" type="text" placeholder="/path/to/slides.md..."
      class="flex-1 min-w-[180px] bg-[var(--background)] text-[var(--foreground)] border border-[var(--border)] rounded-lg px-2.5 py-1 text-xs" />
    <button id="btn-load" type="button"
      class="px-3 py-1 rounded-lg text-xs font-semibold bg-[var(--primary)] text-[var(--primary-foreground)] cursor-pointer">
      Load Deck
    </button>
  </div>
  <iframe id="deck-frame" class="flex-1 w-full rounded-xl border border-[var(--border)] bg-transparent"></iframe>
  <script>
    const params = new URLSearchParams(window.location.search);
    const deckInput = document.getElementById('deck-input');
    const btnLoad = document.getElementById('btn-load');
    const deckFrame = document.getElementById('deck-frame');

    function loadDeck(filePath) {
      if (!filePath) return;
      deckInput.value = filePath;
      const q = new URLSearchParams(window.location.search);
      q.set('file', filePath);
      deckFrame.src = '/api/render-html?' + q.toString();
    }

    btnLoad.addEventListener('click', () => loadDeck(deckInput.value.trim()));
    deckInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') loadDeck(deckInput.value.trim());
    });

    if (params.get('file')) {
      loadDeck(params.get('file'));
    }
  </script>
</body>
</html>`;

app.page('/', () => AUX_VIEW_HTML);
app.page('/view.html', () => AUX_VIEW_HTML);

app.api('/api/bridge-config', (data) => {
  const sessionId = getActiveSessionId(data.session_id || data.sessionId);
  const port = Number(process.env.ANTIGRAVITY_SIDECAR_WEB_PORT || 0);
  const token = process.env.ANTIGRAVITY_SIDECAR_UI_TOKEN || '';
  return {
    baseUrl: port ? `http://127.0.0.1:${port}` : '',
    token,
    conversationId: sessionId,
  };
}, 'GET');

app.api('/api/render-html', (data) => {
  const filePath = normalizeFilePath(data.file || data.path);
  if (!filePath) {
    return new Response('<h3>Marp file not found. Provide ?file=/path/to/slides.md</h3>', {
      status: 404,
      contentType: 'text/html; charset=utf-8',
    });
  }
  const sessionId = getActiveSessionId(data.session_id || data.sessionId);
  const outHtml = `/tmp/marpione_aux_${sessionId}.html`;
  try {
    execFileSync('python3', [MARPIONE_PY, filePath, '--session-id', sessionId, '-o', outHtml], {
      timeout: 120000,
      maxBuffer: 50 * 1024 * 1024,
    });
    const html = execFileSync('cat', [outHtml], { maxBuffer: 50 * 1024 * 1024 });
    return new Response(html, {
      status: 200,
      contentType: 'text/html; charset=utf-8',
    });
  } catch (err) {
    return new Response(`<pre>Error rendering Marp deck:\n${err.message}</pre>`, {
      status: 500,
      contentType: 'text/html; charset=utf-8',
    });
  }
}, 'GET');

// Enable CORS + OPTIONS preflight so inline <agent-embed> widgets can call /_sidecar/send-message
const origRun = app.run.bind(app);
app.run = async () => {
  const server = await origRun();
  const origListeners = server.listeners('request');
  server.removeAllListeners('request');
  server.on('request', (req, res) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, X-Sidecar-Token');
    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }
    for (const listener of origListeners) {
      listener.call(server, req, res);
    }
  });
  return server;
};

await app.run();
